#!/usr/bin/env python3\n\"\"\"K-Eye Forex Trading Bot - Paper Trading Demo.\n\nThis is a standalone CLI to run simulations and paper trading demos.\nNOT FOR LIVE TRADING.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport sys\nfrom app.config import settings\nfrom app.market_data import generate_sample_prices\nfrom app.simulator import run_simulation\nfrom app.reporting import summarize_trades\n\n\ndef print_header() -> None:\n    \"\"\"Print welcome banner.\"\"\"\n    print(\"\\n\" + \"=\"*70)\n    print(\"  K-Eye Forex Trading Bot V1.0 - Paper Trading Demo\")\n    print(\"  ⚠️  EXPERIMENTAL - PAPER TRADING ONLY - NOT FOR REAL MONEY\")\n    print(\"=\"*70 + \"\\n\")\n\n\ndef print_config() -> None:\n    \"\"\"Print trading configuration.\"\"\"\n    print(\"📋 Configuration:\")\n    print(f\"   Market:              {settings.market}\")\n    print(f\"   Starting Balance:    ${settings.starting_balance:.2f}\")\n    print(f\"   Fast EMA:            {settings.fast_ema}\")\n    print(f\"   Slow EMA:            {settings.slow_ema}\")\n    print(f\"   RSI Period:          {settings.rsi_period}\")\n    print(f\"   Risk per Trade:      {settings.risk_per_trade * 100:.1f}%\")\n    print(f\"   Max Positions:       {settings.max_positions}\")\n    print(f\"   Live Trading:        {'✓ ENABLED' if settings.live_trading else '✗ DISABLED (Paper mode)'}\")\n    print()\n\n\ndef demo_paper_trading() -> None:\n    \"\"\"Run a simple paper trading simulation with synthetic prices.\"\"\"\n    print(\"\\n🎯 Demo: Paper Trading Simulation\")\n    print(\"-\" * 70)\n\n    print(\"\\n1️⃣  Generating synthetic price data (60 bars)...\")\n    prices = generate_sample_prices(\n        start=1.1000,\n        drift=0.0005,\n        volatility=0.0015,\n        length=60\n    )\n    print(f\"   ✓ Generated {len(prices.prices)} price bars\")\n    print(f\"   ├─ Start price: ${prices.prices[0]:.5f}\")\n    print(f\"   └─ Final price: ${prices.prices[-1]:.5f}\")\n\n    print(\"\\n2️⃣  Running simulation...\")\n    result = run_simulation(\n        price_series=prices.prices,\n        starting_balance=settings.starting_balance,\n        symbol=\"EURUSD\",\n        fast_period=settings.fast_ema,\n        slow_period=settings.slow_ema,\n        rsi_period=settings.rsi_period,\n        risk_per_trade=settings.risk_per_trade,\n        max_positions=settings.max_positions,\n        stop_loss_pct=0.005,\n    )\n    print(f\"   ✓ Simulation complete\")\n\n    print(\"\\n3️⃣  Trade Summary:\")\n    print(f\"   Total Trades Opened: {len(result.trades)}\")\n    print(f\"   Open Positions:      {sum(1 for t in result.trades if t.status == 'OPEN')}\")\n    print(f\"   Closed Trades:       {sum(1 for t in result.trades if t.status == 'CLOSED')}\")\n\n    report = summarize_trades(result.trades, settings.starting_balance)\n    print(f\"\\n4️⃣  Performance Report:\")\n    print(f\"   Total Trades:        {report.total_trades}\")\n    print(f\"   Win Rate:            {report.win_rate:.1f}%\")\n    print(f\"   Net P&L:             ${report.net_pnl:.4f}\")\n    print(f\"   Final Balance:       ${report.final_balance:.2f}\")\n    if report.total_trades > 0:\n        print(f\"   Avg Trade P&L:       ${report.average_trade_pnl:.4f}\")\n\n    print(f\"\\n5️⃣  Equity Curve (samples):\")\n    equity_samples = result.equity_curve[::max(1, len(result.equity_curve) // 10)]\n    for i, equity in enumerate(equity_samples):\n        pct_change = ((equity - settings.starting_balance) / settings.starting_balance) * 100\n        bar = \"█\" * int(pct_change / 2) if pct_change > 0 else \"▌\" * int(abs(pct_change) / 2)\n        print(f\"   Step {i:2d}: ${equity:.4f} ({pct_change:+6.2f}%) {bar}\")\n\n    print()\n\n\ndef show_trades_detail(result) -> None:\n    \"\"\"Print detailed trade information.\"\"\"\n    if not result.trades:\n        print(\"\\n   No trades executed in this simulation.\")\n        return\n\n    print(\"\\n📊 Detailed Trades:\")\n    print(\"-\" * 70)\n    print(f\"{'#':<3} {'Side':<5} {'Entry':<9} {'Qty':<8} {'Exit':<9} {'P&L':<8} {'Status':<7}\")\n    print(\"-\" * 70)\n\n    for i, trade in enumerate(result.trades, 1):\n        exit_price = f\"${trade.exit_price:.5f}\" if trade.exit_price else \"--\"\n        pnl = f\"${trade.pnl:.4f}\" if trade.pnl is not None else \"--\"\n        print(\n            f\"{i:<3} {trade.side:<5} ${trade.entry_price:<8.5f} {trade.quantity:<8.2f} {exit_price:<9} {pnl:<8} {trade.status:<7}\"\n        )\n\n    print()\n\n\ndef main() -> int:\n    \"\"\"Main CLI entry point.\"\"\"\n    try:\n        print_header()\n        print_config()\n\n        if not settings.live_trading:\n            print(\"✅ Paper trading mode enabled. Running demo...\\n\")\n            demo_paper_trading()\n        else:\n            print(\n                \"❌ ERROR: Live trading is enabled in config!\\n\"\n                \"   This is EXPERIMENTAL software. Live trading is DISABLED by default.\\n\"\n            )\n            return 1\n\n        print(\"\\n\" + \"=\"*70)\n        print(\"  Demo Complete!\")\n        print(\"  For more information, see README.md or visit the GitHub repo.\")\n        print(\"=\"*70 + \"\\n\")\n        return 0\n\n    except Exception as e:\n        print(f\"\\n❌ Error: {e}\", file=sys.stderr)\n        import traceback\n        traceback.print_exc()\n        return 1\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n"